//B"H

import { ensureToken } from "../auth/session.js";
import { getConversation } from "../conversations/detail.js";
import { blobToDataURL } from "../util/blob.js";

/**
 * B"H — ChatGPT audio synthesis helper.
 *
 * Keeps the old endpoint shape, but defaults to MP3 for browser/download use,
 * URL-encodes parameters, and throws clear errors when synthesis fails.
 */
export async function getAwtsmoosAudio(mFetch, {
  message_id,
  conversation_id,
  voice = "orbit",
  format = "mp3",
  download = true
}) {
  if (!conversation_id) throw new Error("conversation_id is required for audio synthesis.");
  const token = await ensureToken(mFetch);
  const convo = await getConversation(mFetch, conversation_id, token);
  const messageId = message_id || convo?.current_node;
  if (!messageId) throw new Error("No assistant message id found for audio synthesis.");
  const url = "https://chatgpt.com/backend-api/synthesize?" + new URLSearchParams({
    message_id: messageId,
    conversation_id,
    voice,
    format
  });
  const response = await mFetch(url, { headers: { authorization: "Bearer " + token } });
  if (!response?.ok) throw new Error(`Audio synthesis failed with status ${response?.status || "unknown"}.`);
  const blob = await response.blob();
  if (download) {
    const href = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = href;
    a.download = "BH_awtsmoosAudio_" + Date.now() + "." + format;
    a.click();
    setTimeout(() => URL.revokeObjectURL(href), 30000);
    return { downloaded: "true" };
  }
  return { url: await blobToDataURL(blob) };
}

geelooy/ai/css/stream-resume-hardening.c.content:
/* B"H
  Chapter 91: The Stream Kept Its Hands While The Page Was Reborn.
  These rules make active streamed event panels easier to open, safer to touch,
  and less likely to hide their controls beneath a constantly changing header.
*/
.transport-details,
.thought-envelope-card,
.event-payload,
.event-long,
.event-object,
.event-array,
.thought-envelope-events {
  overflow-wrap: anywhere;
  scroll-margin-block: 1rem;
}

.transport-details > summary,
.thought-envelope-card > summary,
.event-payload > summary,
.event-long > summary,
.event-object > summary,
.event-array > summary,
.thought-envelope-events > summary {
  min-height: 2.65rem;
  align-content: center;
  touch-action: manipulation;
}

.transport-details[open],
.thought-envelope-card[open] {
  contain: layout paint;
}

.transport-details > .event-panel-actions,
.thought-envelope-card > .event-panel-actions {
  backdrop-filter: blur(10px);
  border-radius: 999px;
  padding: .15rem;
  background: rgba(15, 23, 42, .72);
  box-shadow: 0 8px 24px rgba(0,0,0,.24);
}

.event-panel-actions button {
  font-weight: 800;
  outline-offset: 3px;
}

.transport-details[data-panel-state="minimized"] > summary,
.thought-envelope-card[data-panel-state="minimized"] > summary {
  opacity: .92;
}

.transport-details.is-maximized,
.thought-envelope-card.is-maximized {
  max-width: min(100%, 1180px);
  margin-inline: auto;
}

.event-region,
.thought-inner-window,
.event-lanes {
  content-visibility: auto;
  contain-intrinsic-size: 320px;
}

.transport-details:not([open]) > :not(summary):not(.event-panel-actions),
.thought-envelope-events:not([open]) > :not(summary),
.event-raw-lazy:not([open]) > :not(summary) {
  display: none !important;
}

.thought-inner-window,
.event-lanes,
.event-code-block {
  scrollbar-gutter: stable both-edges;
}

.awtsmoos-audio-offer {
  margin-block-start: .75rem;
  padding: .85rem;
  border: 1px solid rgba(34, 211, 238, .28);
  border-radius: 1rem;
  background: linear-gradient(135deg, rgba(8, 47, 73, .7), rgba(15, 23, 42, .88));
  box-shadow: 0 14px 34px rgba(0, 0, 0, .22);
  display: grid;
  gap: .65rem;
}

.audio-offer-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: .75rem;
}

.audio-offer-head span,
.audio-status {
  color: var(--ai-muted);
  font-size: .85rem;
}

.audio-offer-actions,
.audio-settings {
  display: flex;
  gap: .45rem;
  flex-wrap: wrap;
  align-items: center;
}

.awtsmoos-audio-offer button,
.audio-settings select {
  min-height: 2.2rem;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, .28);
  background: rgba(15, 23, 42, .72);
  color: var(--ai-text);
  padding: .35rem .75rem;
}

.audio-player-wrap audio {
  width: 100%;
  max-width: 560px;
}

@media (max-width: 760px) {
  .transport-details > summary,
  .thought-envelope-card > summary {
    padding-inline-end: 5.8rem !important;
  }

  .transport-details > .event-panel-actions,
  .thought-envelope-card > .event-panel-actions {
    inset-block-start: .38rem;
    inset-inline-end: .38rem;
    gap: .18rem;
  }

  .event-panel-actions button {
    width: 1.65rem !important;
    height: 1.65rem !important;
    min-width: 1.65rem !important;
    min-height: 1.65rem !important;
  }
}
